int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    std::vector<int> v;
    int x;
    while (iss >> x) v.push_back(x);
    std::sort(v.begin(), v.end());
    int a = v[0], b = v[1];
    (void)a;
    int c = 7 - b;
    std::cout << c / gcd(c, 6) << "/" << 6 / gcd(c, 6) << std::endl;
    return 0;
}
